/// `Scene.points`. Element pointers are STABLE across pushes (chunked storage).
class ScenePointsVec {
public:
    explicit ScenePointsVec(ffi::Scene* h) : h_(h) {}
    uint32_t size() const { return ffi::scene_points_len(h_); }
    bool empty() const { return size() == 0; }
    void reserve(uint32_t additional) { ffi::scene_points_reserve(h_, additional); }
    /// Appends a default element and returns a wrapper for it.
    ///
    /// The wrapper holds a pointer INTO the collection, so it follows the
    /// std::vector rule: any later push may reallocate, and every wrapper
    /// taken before it -- including wrappers into collections nested inside
    /// these elements -- is then dangling. Either reserve() the count up
    /// front, or re-take the wrapper with operator[] after the growth.
    /// To hold on to an element across pushes, keep its Ref, not a wrapper.
    Point push() { return Point(ffi::scene_points_push(h_)); }
    /// Wrapper for element `i`; see push() on how long it stays valid.
    Point operator[](uint32_t i) { return Point(ffi::scene_points_at(h_, i)); }
    /// Front/back of a non-empty vec (empty = UB, like STL).
    Point front() { return (*this)[0]; }
    Point back() { return (*this)[size() - 1]; }
    /// Drops the last element; false when already empty.
    bool pop() { return ffi::scene_points_pop(h_); }
    void clear() { ffi::scene_points_clear(h_); }
    void truncate(uint32_t n) { ffi::scene_points_truncate(h_, n); }
    PointRef ref_at(uint32_t i) const { return PointRef{ffi::scene_points_ref_at(h_, i)}; }
    /// Ref of the first/last element; null when empty.
    PointRef first_ref() const { return PointRef{ffi::scene_points_first_ref(h_)}; }
    PointRef last_ref() const { return PointRef{ffi::scene_points_last_ref(h_)}; }
    Point get(PointRef r) { return Point(ffi::scene_points_get(h_, r.raw)); }
    /// True while r addresses a live element here.
    bool contains(PointRef r) const { return ffi::scene_points_contains(h_, r.raw); }
    /// Like get, but empty for a stale or foreign ref.
    option<Point> try_get(PointRef r) {
        ffi::Point* p = ffi::scene_points_try_get(h_, r.raw);
        return p ? option<Point>(Point(p)) : option<Point>();
    }
    /// Bidirectional iterator. Standard C++ contract: modifying the
    /// container while iterating is undefined behavior. Dereference
    /// yields a value wrapper (Point), like vector<bool> --
    /// reference is a value type.
    class iterator {
    public:
        using iterator_category = std::bidirectional_iterator_tag;
        using value_type = Point;
        using difference_type = std::ptrdiff_t;
        using reference = Point;
        struct arrow { Point v; Point* operator->() { return &v; } };
        using pointer = arrow;

        iterator() : h_(nullptr), i_(0) {}
        iterator(ffi::Scene* h, uint32_t i) : h_(h), i_(i) {}
        Point operator*() const { return Point(ffi::scene_points_at(h_, i_)); }
        arrow operator->() const { return arrow{**this}; }
        iterator& operator++() { ++i_; return *this; }
        iterator& operator--() { --i_; return *this; }
        iterator operator++(int) { iterator t = *this; ++*this; return t; }
        iterator operator--(int) { iterator t = *this; --*this; return t; }
        bool operator==(const iterator& o) const { return i_ == o.i_; }
        bool operator!=(const iterator& o) const { return i_ != o.i_; }
    private:
        ffi::Scene* h_;
        uint32_t i_;
    };
    iterator begin() { return iterator(h_, 0); }
    iterator end() { return iterator(h_, size()); }
    class reverse_iterator {
    public:
        using iterator_category = std::bidirectional_iterator_tag;
        using value_type = Point;
        using difference_type = std::ptrdiff_t;
        using reference = Point;
        using pointer = iterator::arrow;

        reverse_iterator() {}
        explicit reverse_iterator(iterator base) : base_(base) {}
        iterator base() const { return base_; }
        Point operator*() const { iterator t = base_; --t; return *t; }
        pointer operator->() const { return pointer{**this}; }
        reverse_iterator& operator++() { --base_; return *this; }
        reverse_iterator& operator--() { ++base_; return *this; }
        reverse_iterator operator++(int) { reverse_iterator t = *this; ++*this; return t; }
        reverse_iterator operator--(int) { reverse_iterator t = *this; --*this; return t; }
        bool operator==(const reverse_iterator& o) const { return base_ == o.base_; }
        bool operator!=(const reverse_iterator& o) const { return base_ != o.base_; }
    private:
        iterator base_;
    };
    reverse_iterator rbegin() { return reverse_iterator(end()); }
    reverse_iterator rend() { return reverse_iterator(begin()); }
private:
    ffi::Scene* h_;
};

